    long long n;
    scanf("%lld", &n);
    const long long MOD = 1000000007;
    long long ans = 1;
    for (long long i = 2; i <= n; i++) { // Start from 2 to avoid multiplying by 1
        ans = ans * i % MOD; // Combine multiplication and modulo in one step
    }
    printf("%lld\n", ans);
    return 0;
}

